/* Bearer auth, same as the Chat Gateway / Stats API. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, openai_error: { error: { message: 'Invalid API key. Provide it via the Authorization header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Platform overview aggregate for the operations console (Phase 1).
   Inputs: chat_executions rows, ops_alerts rows, kb_usage row;
   KB document/chunk counts come from Postgres (kb_* tables). */
const now = Date.now();
const DAY = 86_400_000;
const r2 = (x) => Math.round(x * 1e6) / 1e6;

const execRows = $('Load Exec Rows').all().map((i) => i.json).filter((r) => r && r.status);
const alertRows = $('Load Alerts').all().map((i) => i.json).filter((r) => r && r.kind);
const usageRows = $('Load KB Usage').all().map((i) => i.json);
const usage = usageRows[0] || {};

const d24 = execRows.filter((r) => now - (Date.parse(r.createdAt || '') || 0) <= DAY);
const ok24 = d24.filter((r) => r.status === 'success');
const err24 = d24.filter((r) => r.status !== 'success');
const avgLat = ok24.length ? Math.round(ok24.reduce((s, r) => s + (Number(r.latency_ms) || 0), 0) / ok24.length) : 0;
const cost24 = d24.reduce((s, r) => s + (Number(r.cost_usd) || 0), 0);
const sess = {};
for (const r of d24) sess[r.session_id || 'unknown'] = 1;

let kb = null;
try {
  const { Client } = require('pg');
  const c = new Client({
    host: $env.DB_POSTGRESDB_HOST || 'postgres',
    port: Number($env.DB_POSTGRESDB_PORT || 5432),
    database: $env.DB_POSTGRESDB_DATABASE || 'n8n',
    user: $env.DB_POSTGRESDB_USER || 'n8n',
    password: $env.DB_POSTGRESDB_PASSWORD,
  });
  await c.connect();
  const q = await c.query("SELECT (SELECT count(*) FROM kb_documents WHERE status = 'active') AS documents, (SELECT count(*) FROM kb_chunks) AS chunks");
  await c.end();
  const used = Number(usage.total_embed_tokens || 0);
  const LIMIT = Number($env.EMBED_QUOTA_TOKENS || 1000000);
  kb = {
    documents: Number((q.rows[0] || {}).documents || 0),
    chunks: Number((q.rows[0] || {}).chunks || 0),
    embed_tokens_used: used,
    embed_quota_tokens: LIMIT,
    embed_pct: LIMIT ? Math.round((used / LIMIT) * 1000) / 10 : null,
  };
} catch (e) {
  kb = { error: String(e && e.message ? e.message : e).slice(0, 160) };
}

const alerts = alertRows.slice(0, 12).map((a) => ({
  kind: a.kind,
  message: a.message || '',
  error_rate: a.error_rate,
  created_at: a.createdAt,
}));

return [{ json: {
  ok: true,
  generated_at: new Date().toISOString(),
  chat_24h: {
    total: d24.length,
    success: ok24.length,
    error: err24.length,
    error_rate: d24.length ? Math.round((err24.length / d24.length) * 1000) / 1000 : 0,
    avg_latency_ms: avgLat,
    cost_usd: r2(cost24),
    unique_sessions: Object.keys(sess).length,
  },
  chat_window: { scanned: execRows.length },
  alerts: { recent: alerts, recent_count: alerts.length },
  kb,
} }];

