return [{ json: { ok: true } }];

/* Alert list + delivery channel status for the console. */
const rows = $input.all().map((i) => i.json).filter((r) => r && r.kind);
const alerts = rows.map((r) => ({
  kind: r.kind,
  message: r.message || '',
  error_rate: r.error_rate,
  total: r.total,
  errors: r.errors,
  threshold: r.threshold,
  delivered: r.delivered || null,
  created_at: r.createdAt,
}));
const url = String($env.ALERT_WEBHOOK_URL || '');
return [{ json: { ok: true, delivery: { configured: url.length > 0, format: String($env.ALERT_WEBHOOK_FORMAT || 'generic') }, alerts } }];

/* Bearer auth, same as the Chat Gateway / Stats API. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, openai_error: { error: { message: 'Invalid API key. Provide it via the Authorization header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Send a test notification through the configured alert webhook. */
const url = $env.ALERT_WEBHOOK_URL;
if (!url) {
  return [{ json: { ok: false, reason: 'ALERT_WEBHOOK_URL not configured on n8n - set it in .env and run docker compose up -d n8n', delivery: { configured: false } } }];
}
const fmt = String($env.ALERT_WEBHOOK_FORMAT || 'generic').toLowerCase();
const text = '[PivotAI 控制台] 测试通知 · ' + new Date().toISOString();
let payload;
if (fmt === 'slack' || fmt === 'discord') payload = { text };
else if (fmt === 'feishu') payload = { msg_type: 'text', content: { text } };
else payload = { kind: 'console_test', message: text };
try {
  await this.helpers.httpRequest({ method: 'POST', url, headers: { 'Content-Type': 'application/json' }, body: payload, timeout: 10000 });
  return [{ json: { ok: true, sent: true, format: fmt } }];
} catch (e) {
  return [{ json: { ok: false, reason: 'delivery failed: ' + String(e && e.message ? e.message : e).slice(0, 200), delivery: { configured: true, format: fmt } } }];
}
